import React from 'react';
import EduCert from './EduCert';
import NameCard from './NameCard';
import WorkExperience from './WorkExperience';
import Projects from './Projects';
import VibeProjects from './VibeProjects';
import Skills from './Skills';

const HomePage = () => {
  return (
    <div className='horizontal-scroll-container flex'>
        {/* Home / NameCard Section */}
        <section id="home" className="scroll-section">
          <NameCard />
        </section>

        <section id="projects" className="scroll-section">
          <Projects />
        </section>

        <section id="vibe-projects" className="scroll-section">
          <VibeProjects />
        </section>

        <section id="work-experience" className="scroll-section">
          <WorkExperience />
        </section>

        <section id="skills" className="scroll-section">
          <Skills />
        </section>

        <section id="education" className="scroll-section">
          <EduCert />
        </section>
    </div>
  );
};

export default HomePage;
